#define LOG_MODULE_NAME STREAM_FLASH
#define LOG_LEVEL CONFIG_STREAM_FLASH_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(LOG_MODULE_NAME, CONFIG_STREAM_FLASH_LOG_LEVEL);

#include <zephyr/types.h>
#include <string.h>
#include <zephyr/drivers/flash.h>

#include <zephyr/storage/stream_flash.h>

#ifdef CONFIG_STREAM_FLASH_PROGRESS
#include <zephyr/settings/settings.h>

static int settings_direct_loader(const char *key, size_t len,
				  settings_read_cb read_cb, void *cb_arg,
				  void *param)
{
	struct stream_flash_ctx *ctx = (struct stream_flash_ctx *) param;

	/* Handle the subtree if it is dark, i.e. empty string */
	if (len == 0) {
		return 0;
	}

	if (strcmp(key, "bytes_written") == 0) {
		ssize_t rc = read_cb(cb_arg, &ctx->bytes_written,
				     sizeof(ctx->bytes_written));
		if (rc != sizeof(ctx->bytes_written)) {
			LOG_ERR("Error %zd reading bytes_written", rc);
			return (int) rc;
		}
	}

	return 0;
}

#endif /* CONFIG_STREAM_FLASH_PROGRESS */

#ifdef CONFIG_STREAM_FLASH_ERASE

int stream_flash_erase_page(struct stream_flash_ctx *ctx, off_t off)
{
	int rc;
	struct flash_pages_info page;

	if (!ctx) {
		return -EFAULT;
	}

	/* Do not allow erasing the same page twice.However allow erasing when
	 * intent to reset the writing matches last erased page offset(because
	 * there is no other representation for 'not erased anything yet'
	 * state).
	 */
	if (ctx->erased_up_to != 0 && off < ctx->erased_up_to + ctx->offset) {
		return 0;
	}

	rc = flash_get_page_info_by_offs(ctx->fdev, off, &page);
	if (rc != 0) {
		LOG_ERR("Error %d while getting page info", rc);
		return rc;
	}

	if (ctx->erased_up_to + ctx->offset >= page.start_offset + page.size) {
		return 0;
	}

	LOG_INF("Erasing page at offset 0x%08lx", (long)page.start_offset);

	rc = flash_erase(ctx->fdev, page.start_offset, page.size);

	if (rc != 0) {
		LOG_ERR("Error %d while erasing page", rc);
	} else {
		ctx->erased_up_to = page.start_offset + page.size - ctx->offset;
	}

	return rc;
}

#endif /* CONFIG_STREAM_FLASH_ERASE */

static int flash_sync(struct stream_flash_ctx *ctx)
{
	int rc = 0;
	size_t write_addr = ctx->offset + ctx->bytes_written;
	size_t buf_bytes_aligned;
	size_t fill_length;
	uint8_t filler;

	if (ctx->buf_bytes == 0) {
		return 0;
	}

	if (IS_ENABLED(CONFIG_STREAM_FLASH_ERASE)) {

		rc = stream_flash_erase_page(ctx,
					     write_addr + ctx->buf_bytes - 1);
		if (rc < 0) {
			LOG_ERR("stream_flash_erase_page err %d offset=0x%08zx",
				rc, write_addr);
			return rc;
		}
	}

	fill_length = flash_get_write_block_size(ctx->fdev);
	if (ctx->buf_bytes % fill_length) {
		fill_length -= ctx->buf_bytes % fill_length;
		filler = flash_get_parameters(ctx->fdev)->erase_value;

		memset(ctx->buf + ctx->buf_bytes, filler, fill_length);
	} else {
		fill_length = 0;
	}

	buf_bytes_aligned = ctx->buf_bytes + fill_length;
	rc = flash_write(ctx->fdev, write_addr, ctx->buf, buf_bytes_aligned);

	if (rc != 0) {
		LOG_ERR("flash_write error %d offset=0x%08zx", rc,
			write_addr);
		return rc;
	}

	if (ctx->callback) {
		/* Invert to ensure that caller is able to discover a faulty
		 * flash_read() even if no error code is returned.
		 */
		for (int i = 0; i < ctx->buf_bytes; i++) {
			ctx->buf[i] = ~ctx->buf[i];
		}

		rc = flash_read(ctx->fdev, write_addr, ctx->buf,
				ctx->buf_bytes);
		if (rc != 0) {
			LOG_ERR("flash read failed: %d", rc);
			return rc;
		}

		rc = ctx->callback(ctx->buf, ctx->buf_bytes, write_addr);
		if (rc != 0) {
			LOG_ERR("callback failed: %d", rc);
			return rc;
		}
	}

	ctx->bytes_written += ctx->buf_bytes;
	ctx->buf_bytes = 0U;

	return rc;
}

int stream_flash_buffered_write(struct stream_flash_ctx *ctx, const uint8_t *data,
				size_t len, bool flush)
{
	int processed = 0;
	int rc = 0;
	int buf_empty_bytes;

	if (!ctx) {
		return -EFAULT;
	}

	if (ctx->bytes_written + ctx->buf_bytes + len > ctx->available) {
		return -ENOMEM;
	}

	while ((len - processed) >=
	       (buf_empty_bytes = ctx->buf_len - ctx->buf_bytes)) {
		memcpy(ctx->buf + ctx->buf_bytes, data + processed,
		       buf_empty_bytes);

		ctx->buf_bytes = ctx->buf_len;
		rc = flash_sync(ctx);

		if (rc != 0) {
			return rc;
		}

		processed += buf_empty_bytes;
	}

	/* place rest of the data into ctx->buf */
	if (processed < len) {
		memcpy(ctx->buf + ctx->buf_bytes,
		       data + processed, len - processed);
		ctx->buf_bytes += len - processed;
	}

	if (flush && ctx->buf_bytes > 0) {
		rc = flash_sync(ctx);
	}

	return rc;
}

size_t stream_flash_bytes_written(const struct stream_flash_ctx *ctx)
{
	return ctx->bytes_written;
}

#ifdef CONFIG_STREAM_FLASH_INSPECT
struct _inspect {
	size_t buf_len;
	size_t total_size;
};

static bool find_flash_total_size(const struct flash_pages_info *info,
				  void *data)
{
	struct _inspect *ctx = (struct _inspect *) data;

	if (ctx->buf_len > info->size) {
		LOG_ERR("Buffer size is bigger than page");
		ctx->total_size = 0;
		return false;
	}

	ctx->total_size += info->size;

	return true;
}

/*Internal wrapper for flash_page_foreach */
static void inspect_flash_pages(const struct device *dev,
				struct _inspect *rp)
{
	flash_page_foreach(dev, find_flash_total_size, rp);
}
#else
#define inspect_flash_pages(...) \
	do {                     \
	} while (0)
#endif /* CONFIG_STREAM_FLASH_INSPECT */

int stream_flash_init(struct stream_flash_ctx *ctx, const struct device *fdev,
		      uint8_t *buf, size_t buf_len, size_t offset, size_t size,
		      stream_flash_callback_t cb)
{
	if (ctx == NULL || fdev == NULL || buf == NULL) {
		return -EFAULT;
	}

#ifdef CONFIG_STREAM_FLASH_INSPECT
	struct _inspect rp = {
		.buf_len = buf_len,
		.total_size = 0
	};
#endif

	struct stream_flash_ctx tmp = {
		.fdev = fdev,
		.buf = buf,
		.buf_len = buf_len,
		.bytes_written = 0,
		.buf_bytes = 0,
		.offset = offset,
		.available = size,
		.callback = cb
	};

	if (buf_len % flash_get_write_block_size(fdev)) {
		LOG_ERR("Buffer size is not aligned to minimal write-block-size");
		return -EINVAL;
	}

	inspect_flash_pages(fdev, &rp);

#ifdef CONFIG_STREAM_FLASH_INSPECT
	if (rp.total_size == 0) {
		LOG_ERR("Device seems to have 0 size");
		return -EFAULT;
	}

	if (offset > rp.total_size || rp.total_size - offset < size) {
		LOG_ERR("Incorrect parameter");
		return -EFAULT;
	}

	/* Use total size left on device if size is set to 0 */
	if (size == 0) {
		tmp.available = rp.total_size - offset;
	}
#else
	/* If flash cannot be inspected the size remaining cannot be determined */
	if (size == 0) {
		return -EFAULT;
	}
#endif /* CONFIG_STREAM_FLASH_INSPECT */

#ifdef CONFIG_STREAM_FLASH_ERASE
	tmp.erased_up_to = 0;
#endif

	*ctx = tmp;

	return 0;
}

int stream_flash_progress_load(struct stream_flash_ctx *ctx,
			       const char *settings_key)
{
	if (!IS_ENABLED(CONFIG_STREAM_FLASH_PROGRESS)) {
		return -ENOTSUP;
	}

	if (ctx == NULL || settings_key == NULL) {
		return -EFAULT;
	}

#ifdef CONFIG_STREAM_FLASH_PROGRESS
	int rc = settings_load_subtree_direct(settings_key,
					      settings_direct_loader,
					      (void *) ctx);
	if (rc != 0) {
		LOG_ERR("Error %d while loading progress for \"%s\"",
			rc, settings_key);
	}
	return rc;
#else
	return -ENOTSUP;
#endif
}

int stream_flash_progress_save(const struct stream_flash_ctx *ctx,
			       const char *settings_key)
{
	if (!IS_ENABLED(CONFIG_STREAM_FLASH_PROGRESS)) {
		return -ENOTSUP;
	}

	if (ctx == NULL || settings_key == NULL) {
		return -EFAULT;
	}

#ifdef CONFIG_STREAM_FLASH_PROGRESS
	int rc = settings_save_one(settings_key,
				   &ctx->bytes_written,
				   sizeof(ctx->bytes_written));

	if (rc != 0) {
		LOG_ERR("Error %d while storing progress for \"%s\"",
			rc, settings_key);
	}

	return rc;
#else
	return -ENOTSUP;
#endif
}

int stream_flash_progress_clear(const struct stream_flash_ctx *ctx,
				const char *settings_key)
{
	if (!IS_ENABLED(CONFIG_STREAM_FLASH_PROGRESS)) {
		return -ENOTSUP;
	}

	if (ctx == NULL || settings_key == NULL) {
		return -EFAULT;
	}

#ifdef CONFIG_STREAM_FLASH_PROGRESS
	int rc = settings_delete(settings_key);

	if (rc != 0) {
		LOG_ERR("Error %d while deleting progress for \"%s\"",
			rc, settings_key);
	}

	return rc;
#else
	return -ENOTSUP;
#endif
}
